"""Page copy and sections for the Audubon Inn website."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).parent

def create_pages(config,b,image,photo,title,faq,cta,actions,FAQ,BOOK,EVENT,MAP):
    pages = {}
    def add(file,heading,desc,body,cover='audubon-exterior-1280.webp'):
        pages[file] = (heading+' — The Audubon Inn',desc,body,cover)
    def facts():
        return '<div class="fact-strip wrap" aria-label="At a glance"><div><strong>18</strong><span>guest rooms</span></div><div><strong>9 or 18</strong><span>room blocks</span></div><div><strong>After 2 p.m.</strong><span>check-in · checkout 10 a.m.</span></div><div><strong>Pets welcome</strong><span>extra fee applies</span></div></div>'
    def venue_facts():
        return '<div class="venue-facts"><div><strong>70</strong><span>guests for a comfortable gathering</span></div><div><strong>150</strong><span>people maximum; discuss your layout</span></div><div><strong>9 or 18</strong><span>guest rooms available as a block</span></div></div>'
    def planning():
        return '<div class="planning-list"><div><span>01</span><h3>Share your plans.</h3><p>Send your preferred date, guest count, occasion, and room-block needs.</p></div><div><span>02</span><h3>See the space.</h3><p>Request a tour and talk through layout, food, private bar service, and timing.</p></div><div><span>03</span><h3>Review your quote.</h3><p>Confirm the full cost, inclusions, payment schedule, and agreement before reserving.</p></div></div>'
    def event_questions():
        return faq([FAQ[4],FAQ[3],FAQ[6],FAQ[9]])

    home = f'''<section class="hero improved-hero"><div class="hero-photo">{image('audubon-exterior.jpg','The Audubon Inn exterior on North Main Street in Mayville, Wisconsin',lazy=False,sizes='100vw')}</div><div class="hero-shade"></div><div class="hero-content wrap"><p class="eyebrow">HISTORIC MAYVILLE, WISCONSIN · SINCE 1896</p><h1>Historic stays.<br><em>Celebrations together.</em></h1><p>Make yourself at home at the Audubon Inn.<br>Guest rooms, event space, and the Beaumont Bar,<br>with Horicon Marsh waiting nearby.</p><div class="hero-actions">{b('Check room availability',BOOK,'btn light',True,'availability_click')}{b('Plan a wedding or event','weddings.html','text-link light-text')}</div></div><div class="hero-foot wrap"><span>A LITTLE HISTORY. A LITTLE WILD.</span><span>45 NORTH MAIN STREET · MAYVILLE, WI</span></div></section>{facts()}
<section class="wrap section welcome"><div class="welcome-copy"><p class="eyebrow">A HISTORIC ADDRESS. YOUR NEXT CHAPTER.</p><h2>More time<br><em>with your people.</em></h2><p>Bring family from near and far for a wedding weekend, settle in for a marsh escape, or meet friends for a drink. Our downtown inn brings a stay and a celebration together under one roof.</p>{b('Meet the inn','history.html','text-link')}</div><div class="welcome-picture">{photo('lobby.webp','Historic lobby and wood staircase at the Audubon Inn','A glimpse inside the inn.')}<div class="roundel"><span>HISTORIC</span><strong>1896</strong><span>MAYVILLE, WI</span></div></div></section>
<section class="experiences section"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">COME FOR A STAY. MAKE IT AN OCCASION.</p><h2>Your kind of getaway.</h2></div><p>Choose a room, plan a gathering, or find your place at the Beaumont.</p></div><div class="editorial-grid">'''
    for file,pic,alt,label,heading,copy in [
        ('rooms.html','king.webp','King guest room at the Audubon Inn','REST & RECHARGE','Stay a little longer.','Compare room styles and check live rates.'),
        ('weddings.html','event-space.webp','The Audubon Inn event space with tables and chandeliers','GATHER THOSE NEAR & FAR','Celebrate together.','Event-space rental, private bar service, and 9- or 18-room blocks.'),
        ('bar.html','bar.webp','Wooden bar and seating at the Beaumont Bar','FRIDAY & SATURDAY · 5–10 P.M.','Meet at the Beaumont.','A downtown setting for drinks and conversation.')]:
        home += f'<a class="editorial-card" href="{file}">{image(pic,alt)}<div><span class="tiny">{label}</span><h3>{heading} <span aria-hidden="true">↗</span></h3><p>{copy}</p></div></a>'
    home += f'''</div></div></section><section class="wrap section split"><div><p class="eyebrow">ONE ADDRESS. A WEEKEND TOGETHER.</p><h2>Room to gather.<br><em>A place to stay.</em></h2><p>Our event space accommodates up to 150 people, with around 70 guests for a comfortable gathering. Keep your celebration and your guest rooms close with a 9- or 18-room block.</p>{actions('event')}</div>{photo('event-space.webp','Tables and chandeliers inside the Audubon Inn event space','Your layout and arrangements are planned with the events team.')}</section>
<section class="marsh-feature"><div class="marsh-image">{image('boardwalk.webp','Egret Trail floating boardwalk at Horicon National Wildlife Refuge')}</div><div class="marsh-copy"><p class="eyebrow">FOLLOW YOUR CURIOSITY</p><h2>Open skies.<br><em>A slower weekend.</em></h2><p>Make the inn your base for birdwatching, a scenic outing, and time outdoors around Horicon Marsh.</p>{b('Plan a marsh weekend','marsh-weekend.html','text-link')}</div></section>
<section class="wrap section trust-note"><div><p class="eyebrow">GET TO KNOW THE INN</p><h2>A real place.<br><em>A stay with a story.</em></h2><p>Explore guest photographs and reviews, then find the room or gathering that fits your visit.</p><a class="text-link" href="https://www.tripadvisor.com/Hotel_Review-g60073-d23283867-Reviews-The_Audubon_Inn-Mayville_Wisconsin.html" target="_blank" rel="noopener">Read guest reviews on Tripadvisor ↗</a></div></section><section class="wrap section quick-faq"><div><p class="eyebrow">BEFORE YOU ARRIVE</p><h2>Stay with<br>the details sorted.</h2>{b('Arrival & guest questions','faq.html','text-link')}</div><div>{faq(FAQ[:3])}</div></section>{cta()}'''
    add('index.html','Historic Hotel, Weddings & Events in Mayville WI','Stay in historic downtown Mayville. Explore guest rooms, wedding room blocks, event-space rental, and the Beaumont Bar near Horicon Marsh.',home)

    rooms = title('STAY AT THE AUDUBON','Rooms &amp; suites in<br><em>Mayville, Wisconsin.</em>','Eighteen guest rooms, individual character, and a historic downtown address. Choose your dates once on our live booking page.')+f'<section class="wrap room-overview">{photo("king.webp","King guest room with sitting area at the Audubon Inn","An Audubon Inn king room. Individual layouts and furnishings vary.")}<div class="room-note"><p class="eyebrow">YOUR MAYVILLE GETAWAY</p><h2>Find your<br><em>favorite room.</em></h2><p>Start with a king, queen, double queen, or suite. Compare the basics below, then see available rooms and the full price for your dates.</p>{b("See live rooms & rates",BOOK,external=True,event="availability_click")}<p class="small">Pet-friendly stays are available for an extra fee. Contact the inn about your pet before reserving.</p></div></section>'+facts()
    rooms += '<section class="section wrap"><div class="section-heading"><h2>Compare room styles.</h2><div class="filters" aria-label="Filter room styles"><button class="active" data-filter="all" aria-pressed="true">All rooms</button><button data-filter="king" aria-pressed="false">King</button><button data-filter="queen" aria-pressed="false">Queen</button><button data-filter="suite" aria-pressed="false">Suites</button></div></div><div class="room-grid">'
    for tag,bed,name,copy in [('king','ONE KING BED','King rooms','A king bed, sitting area, desk, television, and bathroom with soaking tub. Ask about classic and corner options.'),('queen','ONE QUEEN BED','Queen rooms','A queen bed, desk, television, and bathroom with soaking tub. Some rooms include a sleeper sofa; check your selected room.'),('double','TWO QUEEN BEDS','Double queen rooms','Two queen beds, a desk area, television, and bathroom with soaking tub.'),('suite','QUEEN BED + SEPARATE LIVING AREA','Classic suites','A queen bedroom and separate living space, mini fridge, television, and bathroom with soaking tub. Sofa arrangements vary.')]:
        rooms += f'<article class="room-card" data-room="{tag}"><span class="tiny">{bed}</span><h3>{name}</h3><p>{copy}</p>{b("View available rooms",BOOK,"text-link",True,"availability_click")}</article>'
    rooms += f'''</div><p class="small" role="status" id="room-filter-status">Showing all room styles.</p><p class="small">These are room-style guides. Confirm the individual room’s occupancy, amenities, full price, fees, and cancellation terms when booking.</p></section><section class="pale-section"><div class="wrap section split">{photo('double.webp','Audubon Inn guest room with two queen beds','Double queen room; layouts vary.')}<div><p class="eyebrow">KEEP YOUR PEOPLE CLOSE</p><h2>A wedding weekend.<br>A shared address.</h2><p>Ask about 9- or 18-room blocks for your group. Check-in starts after 2 p.m.; checkout is at 10 a.m.</p>{b('Explore wedding room blocks','weddings.html','text-link')}{b('Arrival, parking & accessibility','contact.html#arrival','text-link')}</div></div></section>{cta()}'''
    add('rooms.html','Rooms & Suites in Mayville WI','Compare king, queen, double queen, and suite options at the Audubon Inn. Check live rates and availability, arrival times, and pet-friendly stays.',rooms,'king-1280.webp')

    events = title('EVENT SPACE RENTAL IN MAYVILLE WI','Your people.<br><em>Your occasion.</em>','A historic setting for weddings, private parties, reunions, showers, and business gatherings.')+f'''<section class="wrap event-hero">{image('event-space.webp','Audubon Inn event room with tables, chandeliers, and stained-glass windows',lazy=False)}<div><p class="eyebrow">LET’S BRING EVERYONE TOGETHER</p><h2>A gathering<br>with character.</h2><p>Rent our event space and arrange private bar service, with guest rooms in the same hotel. Tell us about your occasion and we’ll discuss a layout and arrangements for your group.</p>{actions('event')}<p class="small">An inquiry starts the planning conversation. Your date is confirmed through your agreement.</p></div></section><section class="wrap section">{venue_facts()}<p class="small">Capacity depends on your setup. Discuss seating, tables, dancing, access needs, and service areas when arranging your event.</p></section>
<section class="pale-section"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">START WITH WHAT MATTERS</p><h2>Your event, clearly planned.</h2></div></div><div class="three-columns"><article><h3>The space.</h3><p>Event-space rental for your gathering. Request a tour to explore the room, layout, setup access, and timing.</p></article><article><h3>The bar.</h3><p>Private bar service for your celebration. Discuss the service window, drink arrangements, staffing, and any minimums in your quote.</p></article><article><h3>The stay.</h3><p>Guest-room blocks of 9 or 18 rooms, subject to availability. Room reservations and event arrangements are confirmed together with the team.</p></article></div></div></section>
<section class="wrap section split"><div><p class="eyebrow">BEFORE YOU COMMIT</p><h2>A quote that<br><em>answers your questions.</em></h2><p>Share your date, guest count, room needs, and priorities so the team can discuss your options.</p><ul class="detail-list"><li>Space rental and the agreed layout</li><li>Food and private bar arrangements</li><li>Furniture, linens, staffing, setup, and cleanup</li><li>Access times, end time, deposits, taxes, and other charges</li><li>Guest-room allocation and cancellation terms</li></ul><p class="small">These are planning questions, not a list of included services. Your written quote defines what is included.</p>{b('Request an event quote',EVENT,external=True,event='event_inquiry_start')}</div>{planning()}</section><section class="wrap section quick-faq"><div><p class="eyebrow">GOOD TO KNOW</p><h2>Plan with confidence.</h2>{b('Wedding planning guide','wedding-guide.html','text-link')}</div><div>{event_questions()}</div></section>{cta('event')}'''
    add('events.html','Event Space Rental & Private Bar in Mayville WI','Plan a private event at the Audubon Inn: up to 150 people, around 70 comfortably, private bar service, and guest-room blocks. Request a quote or tour.',events,'event-space-1280.webp')

    wedding = title('WEDDINGS AT THE AUDUBON INN','Gather those<br><em>near and far.</em>','Bring your celebration and your stay together in historic downtown Mayville. Event-space rental, private bar service, and 9- or 18-room blocks keep your people close.')+f'<section class="wrap wedding-opening">{image("event-space.webp","Audubon Inn event space ready for a gathering",lazy=False,sizes="100vw")}<p class="wedding-caption">One place to gather. More time together.</p>{actions("event")}</section><section class="wrap section">{venue_facts()}</section>'
    wedding += f'''<section class="pale-section"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">STAY CLOSE TO THE CELEBRATION</p><h2>A room for<br><em>your people.</em></h2></div><p>Less travel between your celebration and your room. More time with the people you came to see.</p></div><div class="wedding-blocks"><article><span class="wedding-number">9</span><div><p class="eyebrow">GUEST-ROOM BLOCK</p><h3>A close-knit gathering.</h3><p>Ask about nine rooms for your wedding party, family, or friends.</p></div></article><article><span class="wedding-number">18</span><div><p class="eyebrow">GUEST-ROOM BLOCK</p><h3>Bring everyone together.</h3><p>Ask about all eighteen guest rooms for your group under one roof.</p></div></article></div><p class="small">Room blocks are subject to availability. The team will confirm which rooms are included, who books and pays, release dates, minimum nights, and any exclusive use. An 18-room block does not automatically include every public space.</p></div></section>
<section class="wrap section wedding-story"><div>{photo('double.webp','Two-bed guest room at the Audubon Inn','Guest-room photography from the inn.')}</div><div><p class="eyebrow">FROM THE FIRST HELLO TO GOODNIGHT</p><h2>Stay and<br><em>celebrate together.</em></h2><p>Welcome out-of-town guests, get together in the event space, and raise a glass with private bar service. Your guests can head to their rooms in the same hotel when the celebration winds down.</p><p>Check-in starts after 2 p.m. If you need getting-ready time earlier in the day, discuss room access and whether a previous-night stay would suit your plans.</p>{b('Compare guest rooms','rooms.html','text-link')}</div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">A REAL CELEBRATION AT THE INN</p><h2>Your setting.<br>Your own story.</h2></div></div><div class="wedding-gallery"><article class="ceremony-story"><img src="assets/wedding-event-space.png" alt="Guests watching a wedding ceremony in the Audubon Inn event space" width="177" height="181" loading="lazy"><div><h3>A moment together.</h3><p>A wedding ceremony photographed in our event space. Talk with the team about the room arrangement for your own celebration.</p>{b('Request a venue tour',EVENT,'text-link',True,'tour_request')}</div></article><article>{image('bar.webp','The Beaumont Bar inside the Audubon Inn')}<h3>A reason to toast.</h3><p>Discuss private bar service, food arrangements, timings, and the details that make the day yours.</p>{b('Meet the Beaumont','bar.html','text-link')}</article></div></section>
<section class="pale-section"><div class="wrap section split"><div><p class="eyebrow">A LITTLE PLANNING. MORE TIME TOGETHER.</p><h2>Build your<br><em>wedding weekend.</em></h2><p>Our planning guide covers room blocks, venue questions, arrival, food and bar arrangements, and the next steps toward a quote.</p>{b('Read the wedding planning guide','wedding-guide.html','btn')}</div>{planning()}</div></section><section class="wrap section quick-faq"><div><p class="eyebrow">WEDDING QUESTIONS</p><h2>Start with<br>the details.</h2></div><div>{event_questions()}</div></section>{cta('event')}'''
    wedding += (ROOT / 'wedding-content.html').read_text(encoding='utf-8')
    add('weddings.html','Mayville WI Wedding Venue & 9 or 18 Room Blocks','Gather near and far at the Audubon Inn with wedding event-space rental, private bar service, and 9- or 18-room blocks. Ask about your date or a tour.',wedding,'event-space-1280.webp')

    bar = title('THE BEAUMONT BAR IN MAYVILLE WI','Stay for<br><em>another story.</em>','Drinks, good company, and a historic setting inside the Audubon Inn.')+f'''<section class="wrap bar-layout">{photo('bar.webp','Wooden bar and seating at the Beaumont Bar')}<div class="dark-panel"><p class="eyebrow">FRIDAY & SATURDAY</p><h2>Good drinks.<br>Better company.</h2><div class="bar-hours"><span class="tiny">OPENING HOURS</span><strong>5–10 p.m.</strong><p>Friday and Saturday · Wisconsin time</p></div><p>Meet at the Beaumont for cocktails, beer, and wine. Planning a special trip? Check with the inn about private-event closures.</p>{b('Get directions',MAP,'btn light',True,'directions_click')}</div></section><section class="wrap section split"><div><p class="eyebrow">MAKE AN EVENING OF IT</p><h2>A toast.<br><em>A room upstairs.</em></h2><p>Pair your evening with a stay at the inn. Find an available room, then make yourself at home.</p>{b('Check rooms for your visit',BOOK,external=True,event='availability_click')}</div><div class="bar-note"><h3>What’s pouring?</h3>'''
    if config['bar_menu_url']:
        bar += b('View the drinks menu',config['bar_menu_url'],'btn',True,'menu_view')
    else:
        bar += '<p>Ask the bar team for the current drinks list, prices, and specials. For a group occasion, discuss your drinks preferences with the events team.</p>'+b('Ask the bar team','tel:+19206442087','text-link',event='phone_click')
    bar += f'''<p>See the hotel’s own listing for entertainment announcements and changes.</p>{b('Hotel event updates','https://www.hotelonthemarsh.com/Events.html','text-link',True)}</div></section><section class="pale-section"><div class="wrap section split"><div><p class="eyebrow">PRIVATE BAR SERVICE</p><h2>Raise a glass<br>to your occasion.</h2><p>Plan event-space rental and private bar service for your wedding, reunion, or private party. Discuss your date, guest count, service times, and quote.</p>{b('Ask about private bar service',EVENT,external=True,event='event_inquiry_start')}</div>{photo('event-space.webp','Event space at the Audubon Inn')}</div></section>{cta()}'''
    add('bar.html','The Beaumont Bar in Mayville WI — Friday & Saturday 5–10pm','Visit the Beaumont Bar inside the Audubon Inn, open Friday and Saturday 5–10 p.m. Get directions or ask about private bar service for your event.',bar,'bar-640.webp')

    contact = title('CONTACT & DIRECTIONS','Find your way<br><em>to Mayville.</em>','Questions about a stay, your wedding date, or arrival? Choose the route that fits your plans.')+f'''<section class="wrap contact-layout"><div><p class="eyebrow">THE AUDUBON INN</p><h2>In the heart<br>of downtown.</h2><address>45 North Main Street<br>Mayville, Wisconsin 53050</address><div class="contact-line"><span class="tiny">CALL THE FRONT DESK</span><a href="tel:+19206442087" data-track="phone_click">920-644-2087</a></div><div class="contact-line"><span class="tiny">EMAIL THE INN</span><a href="mailto:hotelonthemarsh@gmail.com">hotelonthemarsh@gmail.com</a></div>{b('Get directions',MAP,external=True,event='directions_click')}</div><div class="contact-form-box"><p class="eyebrow">LET’S START A CONVERSATION</p><h3>Your next step.</h3><p><strong>Rooms and rates</strong><br>Choose dates, compare live availability, and reserve on our booking page.</p>{b('Room availability',BOOK,external=True,event='availability_click')}<p><strong>Weddings, room blocks, and events</strong><br>Prepare your date, guest count, and room needs below, then send the email through your own email app.</p>{b('Prepare an event inquiry',EVENT,external=True,event='event_inquiry_start')}<p class="small">Preparing an inquiry does not send it or reserve a date. For general questions or a change to an existing reservation, call or email the inn.</p></div></section><section class="pale-section" id="arrival"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">BEFORE YOU ARRIVE</p><h2>The essentials,<br><em>in one place.</em></h2></div></div><div class="three-columns"><article><h3>Your stay.</h3><p>Check-in after 2 p.m.<br>Checkout at 10 a.m.</p><p>Arrange arrival instructions before traveling if you need help outside your expected schedule.</p></article><article><h3>Your pet.</h3><p>Pets are welcome for an extra fee. Tell the team about your pet before reserving and confirm the fee for your stay.</p></article><article><h3>Your route.</h3><p>Call for current parking and unloading directions. For access needs, ask about your entrance route, room, bathroom, and any elevator or steps before booking.</p></article></div></div></section>{cta()}'''
    contact = contact.replace('</section><section class="pale-section" id="arrival">', '</section>'+(ROOT/'inquiry-content.html').read_text(encoding='utf-8')+'<section class="pale-section" id="arrival">')
    add('contact.html','Contact, Directions & Arrival in Mayville WI','Find the Audubon Inn at 45 North Main Street, Mayville. Contact the team, get directions, check arrival times, or send a wedding and event inquiry.',contact)
    add('faq.html','Guest Questions — Arrival, Pets, Rooms & Events', 'Plan your Audubon Inn stay: check-in after 2 p.m., checkout at 10 a.m., pet-friendly stays, room blocks, event capacity, and Beaumont Bar hours.',title('GOOD TO KNOW','The details<br><em>make the stay.</em>','Helpful answers for a hotel stay, wedding weekend, or evening at the Beaumont.')+f'<section class="wrap faq-layout"><aside><h2>One more question?</h2><p>Talk with the inn about your plans.</p>{b("Contact the team","contact.html")}</aside><div>{faq(FAQ)}</div></section>'+cta())

    history = title('OUR STORY','A Mayville<br><em>original.</em>','A historic address. A new reason to visit.')+f'<section class="wrap story-layout">{photo("stairs.webp","Historic wooden staircase inside the Audubon Inn")}<div><p class="eyebrow">SINCE 1896</p><h2>History you<br><em>can stay in.</em></h2><p>Originally the Beaumont Hotel, the building was designed by Henry Messmer &amp; Son for Jacob and Anna Mueller. It has been part of downtown Mayville since 1896.</p><p>Today, the Audubon Inn brings eighteen guest rooms, gathering space, and the Beaumont Bar together at 45 North Main Street.</p><div class="timeline"><div><strong>1896</strong><p>The Beaumont Hotel is built.</p></div><div><strong>1988</strong><p>Listed on the National Register of Historic Places.</p></div><div><strong>Your visit</strong><p>A new memory in a place with a story.</p></div></div>{actions()}</div></section>'+cta()
    add('history.html','Historic Audubon Inn & Beaumont Hotel in Mayville WI','Discover the story of Mayville’s historic Audubon Inn, originally the Beaumont Hotel, built in 1896. Stay, celebrate, and make a memory of your own.',history,'lobby-1280.webp')

    for filename,heading,description,cover in [
        ('wedding-guide.html','Wedding Weekend Planning & Room Block Guide','Plan your Audubon Inn wedding weekend with a practical guide to 9- or 18-room blocks, venue layout, private bar service, arrival, and event quotes.','event-space-1280.webp'),
        ('marsh-weekend.html','A Horicon Marsh Weekend from Mayville WI','Plan a slower weekend around Horicon Marsh with the Audubon Inn as your base. Choose a visitor center, check current access, and make time for Mayville.','boardwalk-1280.webp'),
        ('things-to-do.html','Horicon Marsh, Things to Do & Local Events','Explore Horicon Marsh from Mayville, plan your outing, and browse a current-month calendar with upcoming local events and official organizer links.','boardwalk-1280.webp'),
        ('dining.html','Places to Eat near the Audubon Inn in Mayville WI','Plan a local meal during your Audubon Inn stay, including The Meating Place in Mayville, with official menu, directions, and contact links.','audubon-exterior-1280.webp'),
        ('privacy.html','Privacy & Website Use','Learn how the Audubon Inn website handles reservation links, event inquiry providers, optional analytics, and your privacy choices.','audubon-exterior-1280.webp'),
        ('sources.html','Information & Photo Credits','Property information, official destination resources, and credits for photographs used on the Audubon Inn website.','lobby-1280.webp')]:
        source = 'area-content.html' if filename == 'things-to-do.html' else filename.replace('.html','-content.html')
        body = (ROOT / source).read_text(encoding='utf-8')
        if filename == 'things-to-do.html':
            from local_calendar import render_calendar
            body = body.replace('{{LOCAL_CALENDAR}}',render_calendar(ROOT))
        if filename == 'privacy.html':
            body = body.replace('{{ANALYTICS_STATUS}}','Optional Google Analytics is configured and loads only after you allow analytics.' if config['analytics_measurement_id'] else 'Google Analytics is not currently configured on this website. No optional analytics script is loaded.')
        add(filename,heading,description,body,cover)
    return pages
